describe('Search Input Focus on Slash Key Press', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should focus search input when user presses / key', () => {
    // Verify search input is not focused initially
    cy.get('[data-testid="search-input"]').should('not.have.focus');

    // Press / key
    cy.get('body').type('/');

    // Verify search input is now focused
    cy.get('[data-testid="search-input"]').should('have.focus');

    // Verify search input has focus styling
    cy.get('[data-testid="search-input"]').should('have.class', 'focused-state');

    // Verify search input is visible
    cy.get('[data-testid="search-input"]').should('be.visible');
  });

  it('should not focus search input when other keys are pressed', () => {
    // Verify search input is not focused initially
    cy.get('[data-testid="search-input"]').should('not.have.focus');

    // Press Enter key
    cy.get('body').type('{Enter}');

    // Verify search input is not focused
    cy.get('[data-testid="search-input"]').should('not.have.focus');

    // Press Tab key
    cy.get('body').type('{Tab}');

    // Verify search input is not focused
    cy.get('[data-testid="search-input"]').should('not.have.focus');

    // Press Shift + Enter
    cy.get('body').type('{Shift}{Enter}');

    // Verify search input is not focused
    cy.get('[data-testid="search-input"]').should('not.have.focus');
  });
});
